// minimal single-page PDF writer (Helvetica, text only)
function textPdf(lines) {
  const escp = (s) => String(s).replace(/[^\x20-\x7E]/g, (c) => ({ '£': 'GBP ', '–': '-', '—': '-', '’': "'", '‘': "'", '“': '"', '”': '"', '·': '-' }[c] || '?')).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
  let y = 800; const ops = ['BT'];
  lines.forEach((ln, i) => {
    const head = i === 0, section = /^[A-Z][A-Z ]{3,}$/.test(ln) && !head;
    const size = head ? 18 : section ? 12 : 10.5;
    const font = head || section ? '/F2' : '/F1';
    ops.push(`${font} ${size} Tf 1 0 0 1 50 ${y} Tm (${escp(ln)}) Tj`);
    y -= head ? 26 : section ? 18 : 14;
  });
  ops.push('ET');
  const content = ops.join('\n');
  const objs = ['<< /Type /Catalog /Pages 2 0 R >>', '<< /Type /Pages /Kids [3 0 R] /Count 1 >>', '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Contents 4 0 R /Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> >>', `<< /Length ${Buffer.byteLength(content, 'latin1')} >>\nstream\n${content}\nendstream`, '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>'];
  let out = '%PDF-1.4\n'; const offs = [];
  objs.forEach((o, i) => { offs.push(Buffer.byteLength(out, 'latin1')); out += `${i + 1} 0 obj\n${o}\nendobj\n`; });
  const xref = Buffer.byteLength(out, 'latin1');
  out += `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n` + offs.map((o) => String(o).padStart(10, '0') + ' 00000 n \n').join('') + `trailer\n<< /Size ${objs.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  return Buffer.from(out, 'latin1');
}

// Public page: paste a job description, upload CVs (or use the sample set), get a ranked shortlist
const body = `<div class="card"><span class="st st-info">AI CV screener</span>
<h1>Twenty CVs in, a ranked shortlist out, with the reasons written down</h1>
<p class="muted">Paste the job description and upload up to 5 CVs as PDF, or run the sample set (one job, six fictional candidates). Gemini reads every CV against the must-haves and nice-to-haves, scores it, lists strengths, gaps and red flags, and drafts three interview questions. The ranked table goes to Google Sheets and a CSV.</p>
<form method="post" action="${BASE}" id="f" enctype="multipart/form-data">
<label>Job description<textarea name="job" maxlength="6000" placeholder="Paste the job ad or the role summary here, must-haves and nice-to-haves included.">${esc(JOB.text)}</textarea></label>
<label>CVs (PDF, up to 5 files, 4 MB each)<input type="file" name="cvs" accept="application/pdf" multiple></label>
<label><input type="checkbox" name="useSamples" value="1" checked style="width:auto;display:inline;margin-right:8px">Use the six sample CVs instead of uploading (fictional candidates for the job above)</label>
<div class="hp" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div>
<button class="btn" type="submit">Screen the candidates →</button>
<p class="small muted" style="margin-top:12px">Takes 15–40 seconds depending on the number of CVs. Files are read once and not stored; successful runs are not kept in the execution log.</p></form>
<div class="warnbox">Public demo. Do not upload real people's CVs; use the samples or anonymised files. The ranking is a first pass to save reading time, not a hiring decision.</div></div>
<div class="card"><h2>The sample set</h2><p class="small muted">Job: <b>${esc(JOB.title)}</b>. Candidates (all fictional, names from Microsoft's demo companies): ${CVS.map((c, i) => `<a href="${BASE}/sample?id=${i}">${esc(c.lines[0].split(' ').map((w) => w[0] + w.slice(1).toLowerCase()).join(' '))}</a>`).join(' · ')} (download the PDFs to see what the AI reads).</p></div>
<div class="card"><h2>What happens when you press the button</h2><ol class="small" style="margin:0;padding-left:20px">
<li>n8n takes the job text and the CV files (the sample CVs are generated as real PDFs by the workflow itself).</li>
<li><b>Google Gemini</b> reads each PDF directly (no OCR step) and returns structured JSON: score 0–100, verdict, years of relevant experience, must-have coverage, strengths, gaps, red flags, a two-line summary and three interview questions.</li>
<li>The candidates are ranked, written to <b>Google Sheets</b> (Screening tab) and offered as a <b>CSV</b>; a private owner view lists every screening from the last 7 days.</li></ol></div>
<script>
var f = document.getElementById('f'); var cb = f.useSamples, fi = f.cvs;
fi.addEventListener('change', function () { if (fi.files.length) cb.checked = false; });
cb.addEventListener('change', function () { if (cb.checked) fi.value = ''; });
f.addEventListener('submit', function () { var b = this.querySelector('button.btn'); b.textContent = 'Reading the CVs…'; b.style.opacity = '.75'; });
</script>`;
return [{ json: { html: page('AI CV screener – Harborline Software', body) } }];

