const rows = r && r.status === 'done' ? r.candidates.map((c, i) => [i + 1, c.name, c.title, c.location, c.years ?? '', c.score, c.verdict, c.musts.map((m) => `${m.req}: ${m.status}`).join('; '), c.strengths.join('; '), c.gaps.join('; '), c.flags.join('; '), c.summary, c.questions.join(' | '), c.file]) : [];
const csv = '﻿' + [head, ...rows].map((row) => row.map(q).join(',')).join('\r\n');
const slug = r ? r.jobTitle.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 40) : 'screening';
