// minimal single-page PDF writer (Helvetica, text only)
function textPdf(lines) {
  const escp = (s) => String(s).replace(/[^\x20-\x7E]/g, (c) => ({ '£': 'GBP ', '–': '-', '—': '-', '’': "'", '‘': "'", '“': '"', '”': '"', '·': '-' }[c] || '?')).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)');
  let y = 800; const ops = ['BT'];
  lines.forEach((ln, i) => {
    const head = i === 0, section = /^[A-Z][A-Z ]{3,}$/.test(ln) && !head;
    const size = head ? 18 : section ? 12 : 10.5;
    const font = head || section ? '/F2' : '/F1';
    ops.push(`${font} ${size} Tf 1 0 0 1 50 ${y} Tm (${escp(ln)}) Tj`);
    y -= head ? 26 : section ? 18 : 14;
  });
  ops.push('ET');
  const content = ops.join('\n');
  const objs = ['<< /Type /Catalog /Pages 2 0 R >>', '<< /Type /Pages /Kids [3 0 R] /Count 1 >>', '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Contents 4 0 R /Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> >>', `<< /Length ${Buffer.byteLength(content, 'latin1')} >>\nstream\n${content}\nendstream`, '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>'];
  let out = '%PDF-1.4\n'; const offs = [];
  objs.forEach((o, i) => { offs.push(Buffer.byteLength(out, 'latin1')); out += `${i + 1} 0 obj\n${o}\nendobj\n`; });
  const xref = Buffer.byteLength(out, 'latin1');
  out += `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n` + offs.map((o) => String(o).padStart(10, '0') + ' 00000 n \n').join('') + `trailer\n<< /Size ${objs.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  return Buffer.from(out, 'latin1');
}

