const page = (title, body, wide) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${CSS}</style></head><body><main class="wrap${wide ? ' wide' : ''}"><header class="brand"><span class="logo">H</span><span>Harborline Software · CV screener</span><span class="pill">Live demo</span></header>${body}<footer>Live demo built with n8n by Aqib ur Rehman · Harborline Software is a fictional company · uploaded CVs are read once and never stored, the sample candidates are fictional, and the AI ranking is a first pass for a human recruiter, not a decision.</footer></main></body></html>`;
const notFoundPage = () => page('Not found', `<div class="card"><h1>We couldn't find that screening</h1><p class="muted">The link may be old (results are kept for 7 days). Start a new one below.</p><a class="btn" href="${BASE}">Open the CV screener</a></div>`);
// ---- end shared helpers ----

// Owner view: screenings from the last 7 days
const store = $getWorkflowStaticData('global');
const runs = Object.values(store.runs || {}).sort((a, b) => b.createdAt - a.createdAt);
const fmt = (ms) => new Date(ms).toLocaleString('en-GB', { timeZone: 'Europe/London', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
const rows = runs.map((r) => { const s = r.stats || {}; const top = (r.candidates || [])[0]; return `<tr><td>${fmt(r.createdAt)}</td><td><b>${esc(r.jobTitle)}</b><br><span class="muted small">${esc(r.source)} · ${(r.files || []).length} CVs</span></td><td>${s.interview ?? '–'} / ${s.maybe ?? '–'} / ${s.no ?? '–'}</td><td>${top ? `${esc(top.name)} <span class="muted small">(${top.score})</span>` : '–'}</td><td>${r.seconds ?? '–'} s</td><td><a href="${BASE}/result?t=${r.token}" target="_blank">shortlist</a> · <a href="${BASE}/csv?t=${r.token}">csv</a></td></tr>`; }).join('');
const body = `<h1>CV screener – owner view</h1><p class="muted">Last 7 days · ${new Date().toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'medium', timeStyle: 'short' })} UK</p>
<div class="kpis"><div class="kpi"><b>${runs.length}</b>Screenings</div><div class="kpi"><b>${runs.reduce((a, r) => a + (r.candidates || []).length, 0)}</b>CVs read</div><div class="kpi"><b>${runs.reduce((a, r) => a + ((r.stats || {}).interview || 0), 0)}</b>Interview recommendations</div><div class="kpi"><b>${(store.day || {}).count || 0} / 15</b>Screenings today</div></div>
<div class="card" style="overflow-x:auto"><table><tr><th>When</th><th>Role</th><th>Interview / maybe / no</th><th>Top candidate</th><th>Time</th><th>Open</th></tr>${rows || '<tr><td colspan="6">Nothing yet.</td></tr>'}</table></div>
<p class="small muted">Full log: <a href="https://docs.google.com/spreadsheets/d/YOUR_SHEET_ID/edit" target="_blank">Google Sheets (Screening tab)</a> · CVs are never stored; successful executions are not saved.</p>`;
return [{ json: { html: page('CV screener – owner view', body, true) } }];
